"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[47946],{55258:e=>{e.exports=JSON.parse('{"functions":[{"name":"AnimateProjectile","desc":"Plays the full grabhook VFX for the player who fired: flight from the\\nhandle, embed + latch hit, reel-in at `retractSpeed`, then fade out.\\n\\n`onCleanup` runs once when the reel-in completes, or early if `targetPart`\\nor `startAtt` leaves `workspace` (pool reclaim, unequip, death).","params":[{"name":"startAtt","desc":"Muzzle attachment on the tool handle (tether start).","lua_type":"Attachment"},{"name":"targetPart","desc":"The junk part being reeled in.","lua_type":"BasePart"},{"name":"hitPos","desc":"Where the hook was aimed; snapped to the part\'s surface.","lua_type":"Vector3"},{"name":"onCleanup","desc":"Called once when the pull ends.","lua_type":"(() -> ())?"},{"name":"retractSpeed","desc":"Reel speed in studs/s (perks applied); defaults to `Physics.RetractSpeed`.","lua_type":"number?"}],"returns":[],"function_type":"static","source":{"line":304,"path":"src/ReplicatedStorage/SharedModules/GrabHookVisuals.luau"}},{"name":"AnimateObserver","desc":"Plays the grabhook VFX that other players see. The server broadcast comes\\nafter the claim, so the hook starts embedded: latch hit at once, then the\\njunk reels to `startAtt` over `retractTime` and the rig fades out.","params":[{"name":"startAtt","desc":"The collector\'s grabhook muzzle (or a root fallback).","lua_type":"Attachment"},{"name":"targetPart","desc":"The junk part being reeled in.","lua_type":"BasePart"},{"name":"retractTime","desc":"Seconds the reel-in takes (from the server broadcast).","lua_type":"number"},{"name":"onCleanup","desc":"Called once when the pull ends.","lua_type":"(() -> ())?"}],"returns":[],"function_type":"static","source":{"line":330,"path":"src/ReplicatedStorage/SharedModules/GrabHookVisuals.luau"}},{"name":"SelfCheck","desc":"Edit-mode check: fires the owner effect at a test part, steps the loop by\\nhand through every phase and asserts the hook depth and full cleanup.\\nRun: `loadstring(game.ReplicatedStorage.SharedModules.GrabHookVisuals.Source)().SelfCheck()`\\n(needs a fresh-require shim for `require` + `script` when run from loadstring).","params":[],"returns":[{"desc":"","lua_type":"string"}],"function_type":"static","source":{"line":352,"path":"src/ReplicatedStorage/SharedModules/GrabHookVisuals.luau"}}],"properties":[],"types":[],"name":"GrabHookVisuals","desc":"Client-side VFX for the grabhook tool. Every pull is one rig cloned from\\n`ReplicatedStorage.GrabHookVFX`:\\n\\n- `HookHead` \u2014 gunmetal + neon head (pivot at the rear, LookVector = flight\\n  direction) with a `TetherEnd` attachment and a short `Trail`.\\n- `Tether` \u2014 a thin Neon cylinder core (refit every frame so the tether looks\\n  round from every angle) carrying the `Glow` and `Energy` beams.\\n- `HitFX` \u2014 attachment with the latch `LatchRing` + `Burst` emitters, hold\\n  `Sparks` and a `PointLight`.\\n\\nPhases: **flight** (head travels from the handle, trail on, slack rope),\\n**hold** (head embedded `TipDepth` inside the item, latch hit, rope pulls\\ntight, item reels to the handle), **release** (sparks stop, tether and light\\nfade over `ReleaseFadeTime`, everything is destroyed).\\n\\nOne `RenderStepped` connection drives every active rig. Each rig owns one\\n`Janitor`. Tuning: `GrabHookConfig.Effects` and `GrabHookConfig.Physics`.","source":{"line":26,"path":"src/ReplicatedStorage/SharedModules/GrabHookVisuals.luau"}}')}}]);